export type BlocCompareRow = {
  bloc: string;
  siteSharePct: number;
  dalySharePct: number;
  gapRatio: number;
  note: string;
};

/** US / China / Europe vs burden they claim to treat */
export const BLOC_COMPARE: BlocCompareRow[] = [
  {
    bloc: "United States",
