    dalySharePct: 7.2,
    gapRatio: 2.22,
    note: "Country-use share; facility share even higher in oncology (~40%)",
  },
  {
    bloc: "China",
    siteSharePct: 13,
    dalySharePct: 17.8,
    gapRatio: 0.73,
    note: "Rising fast on starts; still under-weight vs national DALY stock",
  },
  {
    bloc: "Western Europe",
